def count_zeros(k):
    """Counts the number of zero digits in the decimal expansion of k."""
    return str(k).count('0')

def has_no_zeros(m):
    """Checks if all digits of m are non-zero."""
    return all(digit != '0' for digit in str(m))

max_m = 99999
max_n = 500 # Increased limit for N

data = []

# Iterate over N
for N in range(1, max_n + 1):
    # Iterate over M (must have no zeros)
    for M in range(11111, max_m + 1):
        if has_no_zeros(M):
            K = M // N
            A = count_zeros(K)
            data.append((M, N, A))

# Find the maximum A observed
max_A = 0
for M, N, A in data:
    if A > max_A:
        max_A = A

# Group by N to see where high A occurs
max_A_per_N = {}
for M, N, A in data:
    if N not in max_A_per_N or A > max_A_per_N[N]:
        max_A_per_N[N] = A

print(f"Maximum A found across N <= {max_n}: {max_A}")

print("\n--- N values that achieved the maximum A (or high A) ---")
high_A_N = {N: A for N, A in max_A_per_N.items() if A >= max_A - 1}
print(f"N values with A >= {max_A - 1}:")
# Print a sample of the results
count = 0
for N, A in sorted(high_A_N.items(), key=lambda item: item[1], reverse=True):
    if count < 10:
        print(f"N={N}: Max A={A}")
        count += 1
    else:
        break
